const json = (data, status = 200, extra = {}) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", ...extra },
  });
const binary = (base64, type) =>
  new Response(
    Uint8Array.from(atob(base64), (c) => c.charCodeAt(0)),
    {
      headers: {
        "content-type": type,
        "cache-control": "public, max-age=604800, immutable",
        "x-content-type-options": "nosniff",
      },
    },
  );
const now = () => new Date().toISOString();
const b64 = (bytes) => btoa(String.fromCharCode(...new Uint8Array(bytes)));
const unb64 = (text) => Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
const random = (n = 32) => {
  const x = new Uint8Array(n);
  crypto.getRandomValues(x);
  return x;
};
async function sha(text) {
  return b64(await crypto.subtle.digest("SHA-256", enc.encode(text)));
}
async function hashPassword(password, salt = random(16)) {
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(password),
    "PBKDF2",
    false,
    ["deriveBits"],
  );
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt, iterations: 100000 },
    key,
    256,
  );
  return { hash: b64(bits), salt: b64(salt) };
}
async function verifyPassword(password, salt, expected) {
  const actual = (await hashPassword(password, unb64(salt))).hash;
  if (actual.length !== expected.length) return false;
  let diff = 0;
  for (let i = 0; i < actual.length; i++)
    diff |= actual.charCodeAt(i) ^ expected.charCodeAt(i);
  return diff === 0;
}
async function ensureDb(db) {
  await db.batch([
    db.prepare(
      "CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, full_name TEXT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('super','user')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL)",
    ),
    db.prepare(
      "CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)",
    ),
    db.prepare(
      "CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, serial_no INTEGER NOT NULL UNIQUE, project_name TEXT NOT NULL, module TEXT NOT NULL, payload TEXT NOT NULL, created_by INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(created_by) REFERENCES users(id))",
    ),
    db.prepare(
      "CREATE TABLE IF NOT EXISTS todos (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, text TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, completed_at TEXT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)",
    ),
    db.prepare(
      "CREATE TABLE IF NOT EXISTS mekik2_rack_types (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, type_no INTEGER NOT NULL, name TEXT NOT NULL, drawing TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id,type_no), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)",
    ),
    db.prepare(
      "CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    ),
    db.prepare(
      "CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id)",
    ),
    db.prepare(
      "CREATE INDEX IF NOT EXISTS projects_user_idx ON projects(created_by, created_at)",
    ),
    db.prepare(
      "CREATE INDEX IF NOT EXISTS todos_user_status_idx ON todos(user_id, completed, created_at)",
    ),
    db.prepare(
      "CREATE INDEX IF NOT EXISTS mekik2_rack_types_user_idx ON mekik2_rack_types(user_id,type_no)",
    ),
  ]);
  const userColumns = await db.prepare("PRAGMA table_info(users)").all();
  if (!userColumns.results.some((column) => column.name === "full_name")) {
    await db.prepare("ALTER TABLE users ADD COLUMN full_name TEXT").run();
  }
  const rackReset = await db.prepare("SELECT value FROM app_settings WHERE key='mekik2_types_reset_v101'").first();
  if (!rackReset) {
    await db.batch([
      db.prepare("DELETE FROM mekik2_rack_types"),
      db.prepare("INSERT INTO app_settings(key,value) VALUES('mekik2_types_reset_v101',?)").bind(now()),
    ]);
  }
}
function cookieToken(request) {
  const m = (request.headers.get("cookie") || "").match(
    /(?:^|;\s*)rafex_session=([^;]+)/,
  );
  return m ? decodeURIComponent(m[1]) : null;
}
async function currentUser(request, db) {
  const token = cookieToken(request);
  if (!token) return null;
  return await db
    .prepare(
      "SELECT u.id,u.full_name,u.username,u.role,u.active FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>? AND u.active=1",
    )
    .bind(await sha(token), now())
    .first();
}
function validOrigin(request) {
  const origin = request.headers.get("origin");
  return !origin || origin === new URL(request.url).origin;
}
async function body(request) {
  try {
    return await request.json();
  } catch {
    return {};
  }
}
const sessionCookie = (token) =>
  `rafex_session=${encodeURIComponent(token)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=604800`;
const clearCookie =
  "rafex_session=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0";
function html() {
  const bytes = Uint8Array.from(atob(HTML_BASE64), (c) => c.charCodeAt(0));
  return addMekik2(new TextDecoder().decode(bytes));
}

async function fetchJson(url, headers = {}) {
  const controller = new AbortController(),
    timer = setTimeout(() => controller.abort(), 7000);
  try {
    const response = await fetch(url, {
      headers: {
        accept: "application/json",
        "user-agent": "Rafex-Hesaplama/1.0 contact@rafex.com.tr",
        ...headers,
      },
      signal: controller.signal,
    });
    if (!response.ok)
      throw new Error(`Harici veri kaynağı ${response.status} yanıtı verdi.`);
    return await response.json();
  } finally {
    clearTimeout(timer);
  }
}
async function firstValid(tasks, validate) {
  return Promise.any(
    tasks.map(async (task) => {
      const value = await task();
      if (!validate(value)) throw new Error("Geçersiz veri");
      return value;
    }),
  );
}
function metWeatherCode(symbol = "") {
  if (symbol.includes("thunder")) return 95;
  if (symbol.includes("snow") || symbol.includes("sleet")) return 71;
  if (symbol.includes("rain")) return 61;
  if (symbol.includes("fog")) return 45;
  if (symbol.includes("cloudy")) return 3;
  if (symbol.includes("partlycloudy")) return 2;
  return 0;
}
let dashboardCache = null;
async function dashboardData() {
  const openMeteo =
    "https://api.open-meteo.com/v1/forecast?latitude=40.8025&longitude=29.4398&current=temperature_2m,apparent_temperature,weather_code,wind_speed_10m&timezone=Europe%2FIstanbul";
  const metNorway =
    "https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=40.8025&lon=29.4398";
  const frankfurter =
    "https://api.frankfurter.dev/v1/latest?base=EUR&symbols=TRY,USD";
  const exchangeRate = "https://open.er-api.com/v6/latest/EUR";
  const weatherPromise = firstValid(
    [() => fetchJson(openMeteo), () => fetchJson(metNorway)],
    (data) => Boolean(data?.current || data?.properties?.timeseries?.[0]),
  );
  const ratesPromise = firstValid(
    [() => fetchJson(frankfurter), () => fetchJson(exchangeRate)],
    (data) => Boolean(data?.rates?.TRY && data?.rates?.USD),
  );
  const [weatherResult, ratesResult] = await Promise.allSettled([
    weatherPromise,
    ratesPromise,
  ]);
  const result = { updatedAt: now(), weather: null, rates: null };
  if (weatherResult.status === "fulfilled") {
    const data = weatherResult.value;
    if (data.current) {
      const current = data.current;
      result.weather = {
        location: "Gebze, Kocaeli",
        temperature: current.temperature_2m,
        apparentTemperature: current.apparent_temperature,
        weatherCode: current.weather_code,
        windSpeed: current.wind_speed_10m,
        time: current.time,
      };
    } else {
      const point = data.properties.timeseries[0],
        details = point.data.instant.details,
        symbol =
          point.data.next_1_hours?.summary?.symbol_code ||
          point.data.next_6_hours?.summary?.symbol_code ||
          "";
      result.weather = {
        location: "Gebze, Kocaeli",
        temperature: details.air_temperature,
        apparentTemperature: details.air_temperature,
        weatherCode: metWeatherCode(symbol),
        windSpeed: details.wind_speed,
        time: point.time,
      };
    }
  }
  if (ratesResult.status === "fulfilled") {
    const data = ratesResult.value,
      eurTry = Number(data.rates.TRY),
      eurUsd = Number(data.rates.USD);
    result.rates = {
      eurTry,
      usdTry: eurTry / eurUsd,
      eurUsd,
      date:
        data.date ||
        data.time_last_update_utc?.slice(0, 16) ||
        new Date().toISOString().slice(0, 10),
    };
  }
  if (result.weather || result.rates) {
    dashboardCache = { ...result };
    return result;
  }
  return dashboardCache ? { ...dashboardCache, stale: true } : result;
}

async function api(request, env, path) {
  const db = env.DB;
  await ensureDb(db);
  if (request.method !== "GET" && !validOrigin(request))
    return json({ error: "Geçersiz istek." }, 403);
  if (path === "/api/bootstrap" && request.method === "GET") {
    const row = await db.prepare("SELECT COUNT(*) AS count FROM users").first();
    return json({ needsSetup: Number(row.count) === 0 });
  }
  if (path === "/api/setup" && request.method === "POST") {
    const count = await db
      .prepare("SELECT COUNT(*) AS count FROM users")
      .first();
    if (Number(count.count) !== 0)
      return json({ error: "Kurulum tamamlanmış." }, 409);
    const x = await body(request),
      fullName = String(x.fullName || "").trim(),
      username = String(x.username || "")
        .trim()
        .toLowerCase(),
      password = String(x.password || "");
    if (
      fullName.length < 3 ||
      fullName.length > 80 ||
      !/^[a-z0-9._-]{3,40}$/.test(username) ||
      password.length < 8
    )
      return json(
        {
          error:
            "Ad soyad gerekli; kullanıcı adı en az 3, şifre en az 8 karakter olmalı.",
        },
        400,
      );
    const p = await hashPassword(password),
      created = now();
    await db
      .prepare(
        "INSERT INTO users(full_name,username,password_hash,password_salt,role,active,created_at) VALUES(?,?,?,?,?,1,?)",
      )
      .bind(fullName, username, p.hash, p.salt, "super", created)
      .run();
    return json({ ok: true });
  }
  if (path === "/api/login" && request.method === "POST") {
    const x = await body(request),
      username = String(x.username || "")
        .trim()
        .toLowerCase(),
      password = String(x.password || "");
    const user = await db
      .prepare("SELECT * FROM users WHERE username=? AND active=1")
      .bind(username)
      .first();
    if (
      !user ||
      !(await verifyPassword(password, user.password_salt, user.password_hash))
    )
      return json({ error: "Kullanıcı adı veya şifre hatalı." }, 401);
    const token = b64(random(32)),
      expires = new Date(Date.now() + 604800000).toISOString();
    await db
      .prepare(
        "INSERT INTO sessions(token_hash,user_id,expires_at,created_at) VALUES(?,?,?,?)",
      )
      .bind(await sha(token), user.id, expires, now())
      .run();
    return json(
      {
        ok: true,
        user: {
          id: user.id,
          full_name: user.full_name,
          username: user.username,
          role: user.role,
        },
      },
      200,
      { "set-cookie": sessionCookie(token) },
    );
  }
  if (path === "/api/logout" && request.method === "POST") {
    const token = cookieToken(request);
    if (token)
      await db
        .prepare("DELETE FROM sessions WHERE token_hash=?")
        .bind(await sha(token))
        .run();
    return json({ ok: true }, 200, { "set-cookie": clearCookie });
  }
  const user = await currentUser(request, db);
  if (!user) return json({ error: "Oturum gerekli." }, 401);
  if (path === "/api/me" && request.method === "GET") return json({ user });
  if (path === "/api/dashboard" && request.method === "GET")
    return json(await dashboardData());
  if (path === "/api/mekik2-types" && request.method === "DELETE") {
    const result = await db
      .prepare("DELETE FROM mekik2_rack_types WHERE user_id=?")
      .bind(user.id)
      .run();
    return json({ ok: true, deleted: Number(result.meta.changes || 0) });
  }
  if (path === "/api/mekik2-types" && request.method === "GET") {
    const rows = await db
      .prepare("SELECT id,type_no,name,drawing,created_at FROM mekik2_rack_types WHERE user_id=? ORDER BY type_no")
      .bind(user.id)
      .all();
    return json({
      types: rows.results.map((row) => ({
        id: row.id,
        typeNo: row.type_no,
        name: row.name,
        drawing: JSON.parse(row.drawing),
        createdAt: row.created_at,
      })),
    });
  }
  if (path === "/api/mekik2-types" && request.method === "POST") {
    const x = await body(request), drawing = x.drawing;
    if (
      !drawing ||
      !drawing.plan ||
      !Array.isArray(drawing.plan.feet) ||
      !Array.isArray(drawing.plan.braces) ||
      !Number(drawing.totalWidth) ||
      !Number(drawing.railLength)
    )
      return json({ error: "Kaydedilecek geçerli bir raf hesabı bulunamadı." }, 400);
    const serialized = JSON.stringify(drawing);
    if (serialized.length > 250000)
      return json({ error: "Raf tipi kaydı çok büyük." }, 413);
    const next = await db
      .prepare("SELECT COALESCE(MAX(type_no),0)+1 AS no FROM mekik2_rack_types WHERE user_id=?")
      .bind(user.id)
      .first();
    const typeNo = Number(next.no), name = `Tip ${typeNo}`, createdAt = now();
    const result = await db
      .prepare("INSERT INTO mekik2_rack_types(user_id,type_no,name,drawing,created_at) VALUES(?,?,?,?,?)")
      .bind(user.id, typeNo, name, serialized, createdAt)
      .run();
    return json({ id: result.meta.last_row_id, typeNo, name, drawing, createdAt }, 201);
  }
  const mekikTypeMatch = path.match(/^\/api\/mekik2-types\/(\d+)$/);
  if (mekikTypeMatch && request.method === "DELETE") {
    const result = await db
      .prepare("DELETE FROM mekik2_rack_types WHERE id=? AND user_id=?")
      .bind(Number(mekikTypeMatch[1]), user.id)
      .run();
    if (!Number(result.meta.changes)) return json({ error: "Raf tipi bulunamadı." }, 404);
    return json({ ok: true });
  }
  if (path === "/api/todos" && request.method === "GET") {
    const rows = await db
      .prepare(
        "SELECT id,text,completed,created_at,completed_at FROM todos WHERE user_id=? ORDER BY completed ASC, CASE WHEN completed=0 THEN created_at ELSE completed_at END DESC, id DESC",
      )
      .bind(user.id)
      .all();
    return json({ todos: rows.results });
  }
  if (path === "/api/todos" && request.method === "POST") {
    const x = await body(request),
      text = String(x.text || "").trim();
    if (!text || text.length > 300)
      return json({ error: "Not 1-300 karakter olmalı." }, 400);
    await db
      .prepare(
        "INSERT INTO todos(user_id,text,completed,created_at) VALUES(?,?,0,?)",
      )
      .bind(user.id, text, now())
      .run();
    return json({ ok: true });
  }
  const todoMatch = path.match(/^\/api\/todos\/(\d+)$/);
  if (todoMatch && request.method === "PATCH") {
    const id = Number(todoMatch[1]),
      x = await body(request);
    if (typeof x.completed === "boolean") {
      const done = x.completed ? 1 : 0;
      await db
        .prepare(
          "UPDATE todos SET completed=?,completed_at=? WHERE id=? AND user_id=?",
        )
        .bind(done, done ? now() : null, id, user.id)
        .run();
    }
    if (typeof x.text === "string") {
      const text = String(x.text).trim();
      if (!text || text.length > 300)
        return json({ error: "Not 1-300 karakter olmalı." }, 400);
      await db
        .prepare("UPDATE todos SET text=? WHERE id=? AND user_id=?")
        .bind(text, id, user.id)
        .run();
    }
    return json({ ok: true });
  }
  if (todoMatch && request.method === "DELETE") {
    await db
      .prepare("DELETE FROM todos WHERE id=? AND user_id=?")
      .bind(Number(todoMatch[1]), user.id)
      .run();
    return json({ ok: true });
  }
  if (path === "/api/users" && request.method === "GET") {
    if (user.role !== "super") return json({ error: "Yetkisiz." }, 403);
    const rows = await db
      .prepare(
        "SELECT id,full_name,username,role,active,created_at FROM users WHERE username NOT LIKE 'deleted_%' ORDER BY id",
      )
      .all();
    return json({ users: rows.results });
  }
  if (path === "/api/users" && request.method === "POST") {
    if (user.role !== "super") return json({ error: "Yetkisiz." }, 403);
    const x = await body(request),
      fullName = String(x.fullName || "").trim(),
      username = String(x.username || "")
        .trim()
        .toLowerCase(),
      password = String(x.password || "");
    if (
      fullName.length < 3 ||
      fullName.length > 80 ||
      !/^[a-z0-9._-]{3,40}$/.test(username) ||
      password.length < 8
    )
      return json(
        {
          error:
            "Ad soyad gerekli; kullanıcı adı en az 3, şifre en az 8 karakter olmalı.",
        },
        400,
      );
    const p = await hashPassword(password);
    try {
      await db
        .prepare(
          "INSERT INTO users(full_name,username,password_hash,password_salt,role,active,created_at) VALUES(?,?,?,?,?,1,?)",
        )
        .bind(fullName, username, p.hash, p.salt, "user", now())
        .run();
    } catch {
      return json({ error: "Bu kullanıcı adı kullanılıyor." }, 409);
    }
    return json({ ok: true });
  }
  const userMatch = path.match(/^\/api\/users\/(\d+)$/);
  if (userMatch && request.method === "PATCH") {
    if (user.role !== "super") return json({ error: "Yetkisiz." }, 403);
    const id = Number(userMatch[1]);
    const x = await body(request);
    if (typeof x.active === "boolean") {
      if (id === Number(user.id) && !x.active)
        return json(
          { error: "Süper kullanıcı kendi hesabını pasifleştiremez." },
          400,
        );
      await db
        .prepare("UPDATE users SET active=? WHERE id=? AND role<>'super'")
        .bind(x.active ? 1 : 0, id)
        .run();
    }
    if (typeof x.fullName === "string") {
      const fullName = String(x.fullName).trim();
      if (fullName.length < 3 || fullName.length > 80)
        return json({ error: "Ad soyad 3-80 karakter olmalı." }, 400);
      await db
        .prepare("UPDATE users SET full_name=? WHERE id=?")
        .bind(fullName, id)
        .run();
    }
    if (typeof x.username === "string") {
      const username = String(x.username).trim().toLowerCase();
      if (!/^[a-z0-9._-]{3,40}$/.test(username))
        return json(
          {
            error:
              "Kullanıcı adı 3-40 karakter olmalı; yalnızca küçük harf, rakam, nokta, tire ve alt çizgi kullanılabilir.",
          },
          400,
        );
      try {
        await db
          .prepare("UPDATE users SET username=? WHERE id=?")
          .bind(username, id)
          .run();
      } catch {
        return json({ error: "Bu kullanıcı adı kullanılıyor." }, 409);
      }
    }
    if (x.password) {
      if (String(x.password).length < 8)
        return json({ error: "Şifre en az 8 karakter olmalı." }, 400);
      const p = await hashPassword(String(x.password));
      await db
        .prepare("UPDATE users SET password_hash=?,password_salt=? WHERE id=?")
        .bind(p.hash, p.salt, id)
        .run();
      await db.prepare("DELETE FROM sessions WHERE user_id=?").bind(id).run();
    }
    return json({ ok: true });
  }
  if (userMatch && request.method === "DELETE") {
    if (user.role !== "super") return json({ error: "Yetkisiz." }, 403);
    const id = Number(userMatch[1]);
    const target = await db
      .prepare("SELECT id,role FROM users WHERE id=?")
      .bind(id)
      .first();
    if (!target) return json({ error: "Kullanıcı bulunamadı." }, 404);
    if (target.role === "super" || id === Number(user.id))
      return json({ error: "Süper kullanıcı hesabı silinemez." }, 400);
    await db.batch([
      db.prepare("DELETE FROM sessions WHERE user_id=?").bind(id),
      db
        .prepare("UPDATE users SET username=?,active=0 WHERE id=?")
        .bind(`deleted_${id}_${Date.now()}`, id),
    ]);
    return json({ ok: true });
  }
  if (path === "/api/projects" && request.method === "GET") {
    const q =
      user.role === "super"
        ? db.prepare(
            "SELECT p.*,u.username FROM projects p JOIN users u ON u.id=p.created_by ORDER BY p.id DESC LIMIT 200",
          )
        : db
            .prepare(
              "SELECT p.*,u.username FROM projects p JOIN users u ON u.id=p.created_by WHERE p.created_by=? ORDER BY p.id DESC LIMIT 200",
            )
            .bind(user.id);
    const rows = await q.all();
    return json({
      projects: rows.results.map((x) => ({
        ...x,
        payload: JSON.parse(x.payload),
      })),
    });
  }
  if (path === "/api/projects" && request.method === "POST") {
    const x = await body(request),
      name = String(x.projectName || "").trim(),
      module = String(x.module || "drive-in");
    if (!name || !x.payload)
      return json({ error: "Proje adı ve hesap verisi gerekli." }, 400);
    const seq = await db
      .prepare("SELECT COALESCE(MAX(serial_no),0)+1 AS no FROM projects")
      .first();
    await db
      .prepare(
        "INSERT INTO projects(serial_no,project_name,module,payload,created_by,created_at) VALUES(?,?,?,?,?,?)",
      )
      .bind(seq.no, name, module, JSON.stringify(x.payload), user.id, now())
      .run();
    return json({ ok: true, serialNo: seq.no });
  }
  const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && request.method === "DELETE") {
    const id = Number(projectMatch[1]);
    const project = await db
      .prepare("SELECT id,created_by FROM projects WHERE id=?")
      .bind(id)
      .first();
    if (!project) return json({ error: "Proje kaydı bulunamadı." }, 404);
    if (user.role !== "super" && Number(project.created_by) !== Number(user.id))
      return json({ error: "Bu projeyi silme yetkiniz yok." }, 403);
    await db.prepare("DELETE FROM projects WHERE id=?").bind(id).run();
    return json({ ok: true });
  }
  return json({ error: "Bulunamadı." }, 404);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url),
      path = url.pathname;
    if (path === "/manifest.webmanifest")
      return new Response(APP_MANIFEST, {
        headers: {
          "content-type": "application/manifest+json; charset=utf-8",
          "cache-control": "public, max-age=3600",
          "x-content-type-options": "nosniff",
        },
      });
    if (path === "/service-worker.js")
      return new Response(SERVICE_WORKER, {
        headers: {
          "content-type": "text/javascript; charset=utf-8",
          "cache-control": "no-cache",
          "service-worker-allowed": "/",
          "x-content-type-options": "nosniff",
        },
      });
    if (path === "/app-icon-192.png")
      return binary(APP_ICON_192_BASE64, "image/png");
    if (path === "/app-icon-512.png")
      return binary(APP_ICON_512_BASE64, "image/png");
    if (path === "/rafex-logo.png")
      return binary(RAFEX_LOGO_BASE64, "image/png");
    if (path.startsWith("/api/")) return api(request, env, path);
    if (path !== "/" && path !== "/index.html")
      return new Response("Not found", { status: 404 });
    return new Response(html(), {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
        "x-content-type-options": "nosniff",
        "content-security-policy":
          "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; worker-src 'self'; manifest-src 'self'; frame-ancestors 'none'",
      },
    });
  },
};
